/* @lc app=leetcode id=3288 lang=kotlin */ class Solution { fun lis(c: List<IntArray>): Int = c.sortedWith(compareBy({ it[0] }, { -it[1] })).map { it[1] }.fold(ArrayList<Int>()) { t, y -> t.also { t.binarySearch(y).let { r -> (if (r >= 0) r else -r - 1).let { i -> if (i == t.size) t.add(y) else t.set(i, y) } } } }.size fun maxPathLength(coordinates: Array<IntArray>, k: Int): Int = coordinates[k].let { (px, py) -> lis(coordinates.filter { it[0] < px && it[1] < py }) + 1 + lis(coordinates.filter { it[0] > px && it[1] > py }) } }